SETTLED = {'3-4': '2-6 A', '3-5': '2-3 C', '4-1': '3-2 A', '4-4': '주문 3-4 A', '4-6': '1-5 A', '4-11': '주문 8-2 A', '5-2': '5-1 B',
           '5-7': '6-1 A·6-2 A', '5-8': '6-4 B', '6-6': '6-5 A', '7-5': '4-10 A·1-5 A', '7-6': '1-2 A', '8-4': '1-8 A', '8-5': '1-8 A·7-7 A', '8-7': '8-6 C의 근거'}
